#include <stdio.h>
#include <math.h>

typedef struct {
    double x, y;
} Point;

void koch(int n, Point p1, Point p2) {
    if (n == 0) {
        // Base case: just draw the segment (but we only output points)
        return;
    }

    // Calculate points s, u, t
    Point s, u, t;

    // s is at 1/3 of the segment
    s.x = p1.x + (p2.x - p1.x) / 3.0;
    s.y = p1.y + (p2.y - p1.y) / 3.0;

    // t is at 2/3 of the segment
    t.x = p1.x + 2.0 * (p2.x - p1.x) / 3.0;
    t.y = p1.y + 2.0 * (p2.y - p1.y) / 3.0;

    // u is the apex of the equilateral triangle
    // Rotate vector (t - s) by 60 degrees counterclockwise
    double dx = t.x - s.x;
    double dy = t.y - s.y;
    double angle = M_PI / 3.0; // 60 degrees in radians
    u.x = s.x + dx * cos(angle) - dy * sin(angle);
    u.y = s.y + dx * sin(angle) + dy * cos(angle);

    // Recursive calls for the four subsegments
    koch(n - 1, p1, s);
    printf("%.8f %.8f\n", s.x, s.y);
    koch(n - 1, s, u);
    printf("%.8f %.8f\n", u.x, u.y);
    koch(n - 1, u, t);
    printf("%.8f %.8f\n", t.x, t.y);
    koch(n - 1, t, p2);
}

int main() {
    int n;
    scanf("%d", &n);

    Point p1 = {0.0, 0.0};
    Point p2 = {100.0, 0.0};

    // Print the starting point
    printf("%.8f %.8f\n", p1.x, p1.y);

    // Generate the Koch curve
    koch(n, p1, p2);

    // Print the ending point
    printf("%.8f %.8f\n", p2.x, p2.y);

    return 0;
}

#include <stdio.h>
#include <math.h>

void koch(double x1, double y1, double x2, double y2, int n) {
    if (n == 0) {
        // This segment is a leaf; the caller handles printing
        return;
    }
    double sx = x1 + (x2-x1)/3.0;
    double sy = y1 + (y2-y1)/3.0;
    double tx = x1 + 2.0*(x2-x1)/3.0;
    double ty = y1 + 2.0*(y2-y1)/3.0;
    double dx = tx - sx;
    double dy = ty - sy;
    double ux = (sx+tx)/2.0 - dy*sqrt(3.0)/2.0;
    double uy = (sy+ty)/2.0 + dx*sqrt(3.0)/2.0;

    koch(x1,y1, sx,sy, n-1);
    printf("%.6f %.6f\n", sx, sy);
    koch(sx,sy, ux,uy, n-1);
    printf("%.6f %.6f\n", ux, uy);
    koch(ux,uy, tx,ty, n-1);
    printf("%.6f %.6f\n", tx, ty);
    koch(tx,ty, x2,y2, n-1);
}

