    koch(0.0, 0.0, 100.0, 0.0, n);
    printf("%.6f %.6f\n", 100.0, 0.0);
    return 0;
}

#include <stdio.h>
#include <math.h>

typedef struct {
    double x, y;
} Point;

void koch(int n, Point p1, Point p2) {
    if (n == 0) return;

    Point s, t, u;
    double th = M_PI / 3.0;

    s.x = (2.0 * p1.x + p2.x) / 3.0;
    s.y = (2.0 * p1.y + p2.y) / 3.0;

    t.x = (p1.x + 2.0 * p2.x) / 3.0;
    t.y = (p1.y + 2.0 * p2.y) / 3.0;

    u.x = (t.x - s.x) * cos(th) - (t.y - s.y) * sin(th) + s.x;
    u.y = (t.x - s.x) * sin(th) + (t.y - s.y) * cos(th) + s.y;

    koch(n - 1, p1, s);
    printf("%.8f %.8f\n", s.x, s.y);

    koch(n - 1, s, u);
    printf("%.8f %.8f\n", u.x, u.y);

    koch(n - 1, u, t);
    printf("%.8f %.8f\n", t.x, t.y);

    koch(n - 1, t, p2);
}

