const double PI = acos(-1.0);

void koch(int n, const Point& p1, const Point& p2) {
    if (n == 0) return;

    Point s, t, u;
    s.x = (2.0 * p1.x + p2.x) / 3.0;
    s.y = (2.0 * p1.y + p2.y) / 3.0;

    t.x = (p1.x + 2.0 * p2.x) / 3.0;
    t.y = (p1.y + 2.0 * p2.y) / 3.0;

    double dx = t.x - s.x;
    double dy = t.y - s.y;

    u.x = dx * cos(PI / 3.0) - dy * sin(PI / 3.0) + s.x;
    u.y = dx * sin(PI / 3.0) + dy * cos(PI / 3.0) + s.y;

    koch(n - 1, p1, s);
    cout << fixed << setprecision(8) << s.x << " " << s.y << "\n";

    koch(n - 1, s, u);
    cout << fixed << setprecision(8) << u.x << " " << u.y << "\n";

    koch(n - 1, u, t);
    cout << fixed << setprecision(8) << t.x << " " << t.y << "\n";

    koch(n - 1, t, p2);
}

