import java.util.*;

public class KochCurve {

    static class Point {
        double x, y;
        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        sc.close();

        List<Point> points = new ArrayList<>();
        points.add(new Point(0, 0));
        points.add(new Point(100, 0));

        for (int i = 0; i < n; i++) {
            List<Point> newPoints = new ArrayList<>();
            for (int j = 0; j < points.size() - 1; j++) {
                Point p1 = points.get(j);
                Point p2 = points.get(j + 1);

                // Calculate points s, u, t
                Point s = new Point(
                    (2 * p1.x + p2.x) / 3,
                    (2 * p1.y + p2.y) / 3
                );
                Point t = new Point(
                    (p1.x + 2 * p2.x) / 3,
                    (p1.y + 2 * p2.y) / 3
                );

                // Rotate vector (t - s) by 60 degrees to get u
                double dx = t.x - s.x;
                double dy = t.y - s.y;
                Point u = new Point(
                    s.x + (dx * Math.cos(Math.PI / 3) - dy * Math.sin(Math.PI / 3)),
                    s.y + (dx * Math.sin(Math.PI / 3) + dy * Math.cos(Math.PI / 3))
                );

                newPoints.add(p1);
                newPoints.add(s);
                newPoints.add(u);
                newPoints.add(t);
            }
            newPoints.add(points.get(points.size() - 1));
            points = newPoints;
        }

        // Output all points
        for (Point p : points) {
            System.out.printf("%.8f %.8f%n", p.x, p.y);
        }
    }
}

import java.io.*;
