public class Main {
    static StringBuilder sb = new StringBuilder();

    static class Point {
        double x, y;
        Point(double x, double y) {
            this.x = x;
            this.y = y;
        }
    }

    static void koch(int n, Point p1, Point p2) {
        if (n == 0) return;

        double sx = (2.0 * p1.x + p2.x) / 3.0;
        double sy = (2.0 * p1.y + p2.y) / 3.0;
        double tx = (p1.x + 2.0 * p2.x) / 3.0;
        double ty = (p1.y + 2.0 * p2.y) / 3.0;

        double ux = (tx - sx) * Math.cos(Math.PI / 3.0) - (ty - sy) * Math.sin(Math.PI / 3.0) + sx;
        double uy = (tx - sx) * Math.sin(Math.PI / 3.0) + (ty - sy) * Math.cos(Math.PI / 3.0) + sy;

        Point s = new Point(sx, sy);
        Point u = new Point(ux, uy);
        Point t = new Point(tx, ty);

        koch(n - 1, p1, s);
        appendPoint(s);
        koch(n - 1, s, u);
        appendPoint(u);
        koch(n - 1, u, t);
        appendPoint(t);
        koch(n - 1, t, p2);
    }

    static void appendPoint(Point p) {
        sb.append(String.format(Locale.US, "%.8f %.8f%n", p.x, p.y));
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());

        Point p1 = new Point(0.0, 0.0);
        Point p2 = new Point(100.0, 0.0);

        appendPoint(p1);
        koch(n, p1, p2);
        appendPoint(p2);

        System.out.print(sb.toString());
    }
}
